# Na računaru bi ovo bila dva fajla.
# racunanje.py:
def kvadrat(x):
    return x * x


def kub(x):
    return x * x * x


# main.py (uz: from racunanje import kvadrat, kub):
def main():
    for n in range(1, 4):
        print(n, kvadrat(n), kub(n))


print("__name__ je:", __name__)

if __name__ == "__main__":
    main()

exercise.solution:
def kvadrat(x):
    return x * x


def opis_broja(n):
    vrsta = "paran" if n % 2 == 0 else "neparan"
    return f"Broj {n} je {vrsta}, a njegov kvadrat je {kvadrat(n)}."


def main():
    n = int(input("Broj: "))
    print(opis_broja(n))


if __name__ == "__main__":
    main()

